//! `netinet/if_fddi.h` (and the kernel's `linux/if_fddi.h` it includes): the FDDI frame header structures and constants.
//! Plain data; the C header is include-static/netinet/if_fddi.h (generated by tools/gen_net_extra.py), and
//! tests/c/net_extra_test.c checks that it gives glibc's layouts and values.
use core::mem::{offset_of, size_of};

/// Octets in one FDDI address.
pub const FDDI_K_ALEN: usize = 6;
/// Total octets in an 802.2 header.
pub const FDDI_K_8022_HLEN: usize = 16;
/// Total octets in an 802.2 SNAP header.
pub const FDDI_K_SNAP_HLEN: usize = 21;
/// Max octets in an 802.2 payload.
pub const FDDI_K_8022_DLEN: usize = 4475;
/// Max octets in an 802.2 SNAP payload.
pub const FDDI_K_SNAP_DLEN: usize = 4470;
/// Min octets in an LLC frame without FCS.
pub const FDDI_K_LLC_ZLEN: usize = 13;
/// Max octets in an LLC frame without FCS.
pub const FDDI_K_LLC_LEN: usize = 4491;
/// Octets in the OUI of an 802.2 SNAP header.
pub const FDDI_K_OUI_LEN: usize = 3;
/// Frame control: class bit.
pub const FDDI_FC_K_CLASS_MASK: u8 = 0x80;
/// Frame control: LLC format.
pub const FDDI_FC_K_FORMAT_LLC: u8 = 0x10;
/// Frame control: default asynchronous LLC frame.
pub const FDDI_FC_K_ASYNC_LLC_DEF: u8 = 0x54;
/// Frame control: non-restricted token.
pub const FDDI_FC_K_NON_RESTRICTED_TOKEN: u8 = 0x80;
/// The SAP of a SNAP header.
pub const FDDI_EXTENDED_SAP: u8 = 0xAA;
/// The control byte of an unnumbered information frame.
pub const FDDI_UI_CMD: u8 = 0x03;

/// `struct fddi_header` (netinet/if_fddi.h).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct FddiHeader {
    pub fddi_fc: u8,
    pub fddi_dhost: [u8; FDDI_K_ALEN],
    pub fddi_shost: [u8; FDDI_K_ALEN],
}

/// `struct fddi_8022_1_hdr`: 802.2 type 1 header.
#[repr(C, packed)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Fddi80221Hdr {
    pub dsap: u8,
    pub ssap: u8,
    pub ctrl: u8,
}

/// `struct fddi_8022_2_hdr`: 802.2 type 2 header.
#[repr(C, packed)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Fddi80222Hdr {
    pub dsap: u8,
    pub ssap: u8,
    pub ctrl_1: u8,
    pub ctrl_2: u8,
}

/// `struct fddi_snap_hdr`: 802.2 SNAP header (`ethertype` is big-endian).
#[repr(C, packed)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct FddiSnapHdr {
    pub dsap: u8,
    pub ssap: u8,
    pub ctrl: u8,
    pub oui: [u8; FDDI_K_OUI_LEN],
    pub ethertype: u16,
}

/// The LLC part of a `struct fddihdr`.
#[repr(C, packed)]
#[derive(Clone, Copy)]
pub union FddiLlc {
    pub llc_8022_1: Fddi80221Hdr,
    pub llc_8022_2: Fddi80222Hdr,
    pub llc_snap: FddiSnapHdr,
}

/// `struct fddihdr`: an FDDI LLC frame header.
#[repr(C, packed)]
#[derive(Clone, Copy)]
pub struct Fddihdr {
    pub fc: u8,
    pub daddr: [u8; FDDI_K_ALEN],
    pub saddr: [u8; FDDI_K_ALEN],
    pub hdr: FddiLlc,
}

// glibc 2.43, as printed by tests/c/net_extra_test.c
const _: () = {
    assert!(size_of::<FddiHeader>() == 13);
    assert!(offset_of!(FddiHeader, fddi_dhost) == 1);
    assert!(offset_of!(FddiHeader, fddi_shost) == 7);
    assert!(size_of::<Fddi80221Hdr>() == 3);
    assert!(size_of::<Fddi80222Hdr>() == 4);
    assert!(size_of::<FddiSnapHdr>() == 8);
    assert!(offset_of!(FddiSnapHdr, oui) == 3);
    assert!(offset_of!(FddiSnapHdr, ethertype) == 6);
    assert!(size_of::<Fddihdr>() == 21);
    assert!(offset_of!(Fddihdr, daddr) == 1);
    assert!(offset_of!(Fddihdr, saddr) == 7);
    assert!(offset_of!(Fddihdr, hdr) == 13);
};
